#!/bin/bash
# Task 148-w10-quiet -- meshsim sim/ WORKER10 (branch sim-w10; kit: after 275655e). TIMING TASK: keep the box quiet while it runs.
# The quiet case (W10; PLAN-M2): does a mostly idle machine pay per cycle for its size? (1) N units on one thread, K
# busy, the rest asleep with idle Links (bench_threads --form 4): N 64, 1024, 16384, 131072; K 1, 8, 64; perf stat.
# (2) W9's chip in windows of 64 cycles (bench_chip --windows, 9 machines after an untimed one): the boot and wfi, cost
# per cycle by steps a cycle. One revision (275655e). 5 repeats. ~4 min.
# From an embedded kit (sim/ at each revision named above). Writes only results/148-w10-quiet/. Scratch in /tmp, removed first
# and at the end. Safe to re-run.
set -u
cd "$(dirname "$0")/.."
REPO=$PWD; RES=$REPO/results/148-w10-quiet; mkdir -p "$RES"; rm -f "$RES/raw.txt"
W=/tmp/w10-148-w10-quiet; rm -rf "$W"; mkdir -p "$W"
sed -n '/^__KIT_BEGIN__$/,/^__KIT_END__$/p' "$0" | sed '1d;$d' | base64 -d > "$W/kit.tgz" || exit 2
GOT=$(sha256sum "$W/kit.tgz" | cut -d' ' -f1); echo "kit sha256 $GOT"
[ "$GOT" = "51381e037350e51e0f276a9989216c1e6434be2058d6b05930aaec6fb97f4727" ] || { echo "kit sha256 mismatch (want 51381e037350e51e0f276a9989216c1e6434be2058d6b05930aaec6fb97f4727)"; exit 2; }
mkdir -p "$W/kit" && tar -xzf "$W/kit.tgz" -C "$W/kit" || exit 2
KITS="after"
FAILS=0; FAIL=0
sec() { echo; echo "==== $*  [$(date +%T)]"; }
verdict() { echo "VERDICT $1: $2"; [ "$2" = PASS ] || FAIL=1; }
START=$(date +%s)
{
sec "machine (D21)"; . "$W/kit/after/sim/tools/machine.sh" "${QUEST_P_CPUS:-}" "${QUEST_E_CPUS:-}"; machine_record "$RES/machine.txt"; uptime
echo "kit: after 275655e"
# Shared by W10's task bodies. run TAG CPUSET cmd...: one run under taskset (and perf stat when PERF=1: cycles,
# instructions, L1d load misses, LLC load misses, summed per core type); appends "TAG <bench line> [perf: ...]" to
# $RES/raw.txt. field NAME: a key=value field of stdin's lines.
run() {
  local tag=$1 cpus=$2; shift 2
  command -v perf > /dev/null || PERF=0
  if [ "${PERF:-0}" = 1 ]; then
    taskset -c "$cpus" perf stat -x, -e cycles,instructions,L1-dcache-load-misses,LLC-load-misses -o "$W/perf.csv" -- "$@" \
      > "$W/out.txt" 2> "$W/err.txt"
  else
    taskset -c "$cpus" "$@" > "$W/out.txt" 2> "$W/err.txt"
  fi
  local rc=$?
  local line; line=$(grep -E '^(threads|chip) ' "$W/out.txt" | tail -1)
  if [ $rc -ne 0 ] || [ -z "$line" ]; then echo "RUNFAIL $tag rc=$rc: $*"; head -5 "$W/err.txt"; FAILS=$((FAILS + 1)); return 1; fi
  local pc=""
  [ "${PERF:-0}" = 1 ] && pc=" perf: $(awk -F, '$1 ~ /^[0-9]+$/ { n=split($3,a,"/"); ev=(n>1)?a[2]:a[1]; k=(a[1]=="cpu_atom")?"atom":"core";
      v[k "_" ev]+=$1 } END { for (x in v) printf "%s=%s ", x, v[x] }' "$W/perf.csv")"
  echo "$tag $line$pc" | tee -a "$RES/raw.txt"
}
field() { grep -o "$1=[^ ]*" | cut -d= -f2; }
# med TAG FIELD: the median of FIELD over raw.txt's lines starting "TAG "
med() { grep "^$1 " "$RES/raw.txt" | field "$2" | sort -g | awk '{ a[NR]=$1 } END { if (NR) print a[int((NR+1)/2)]; else print "-" }'; }
# Task body (WORKER10): the quiet case (PLAN-M2, the owner's expectation): cost per cycle against the number of active
# units. (1) bench_threads --form 4: N units on one thread, K busy (a little hashing and a put each cycle), the rest
# asleep (a Link in and out each, never used): N = 64, 1024, 16384, 131072; K = 1, 8, 64; perf stat (cycles,
# instructions, L1d and LLC load misses). (2) W9's chip in windows of 64 cycles (bench_chip --windows): the boot and wfi,
# cost per cycle by steps a cycle. REPS (default 5).
REPS=${REPS:-5}
sec "build (clang release, D18)"
for k in $KITS; do
  ( cd "$W/kit/$k/sim" && make -j8 CC_NAME=clang MODE=release build/clang-release/bench_threads build/clang-release/bench_chip > "$RES/build-$k.log" 2>&1 ) \
    || { tail -20 "$RES/build-$k.log"; verdict "build $k" FAIL; exit 1; }
done
P1=$(take 1 "$P_ONE")
for rep in $(seq $REPS); do for k in $KITS; do B=$W/kit/$k/sim/build/clang-release/bench_threads
  for n in 64 1024 16384 131072; do for a in 1 8 64; do
    [ $a -gt $n ] && continue
    PERF=1 run "$k q-n$n-k$a" "$P1" $B --form 4 --units $n --active $a --cycles 400000 --warmup 5000 --cpus "$P1"
  done; done
done; done
for k in $KITS; do for p in sort wfi; do
  ( cd "$W/kit/$k/sim" && taskset -c "$P1" ./build/clang-release/bench_chip --prog $p --windows 64 --reps 9 > "$RES/windows-$k-$p.txt" 2>&1 ) || echo "RUNFAIL windows $p"
done; done
sec "summary: medians; us per cycle and instructions per cycle (perf: the run's, build and warmup included) against N, K"
for k in $KITS; do for a in 1 8 64; do for n in 64 1024 16384 131072; do
  u=$(med "$k q-n$n-k$a" us_per_cycle); [ "$u" = - ] && continue
  ins=$(med "$k q-n$n-k$a" core_instructions); cyc=$(med "$k q-n$n-k$a" core_cycles); l1=$(med "$k q-n$n-k$a" core_L1-dcache-load-misses); llc=$(med "$k q-n$n-k$a" core_LLC-load-misses)
  printf "%s active=%-3s units=%-7s us_per_cycle=%-8s ns_per_active_step=%-7s words=%-8s perf(all): instr=%s cycles=%s l1_miss=%s llc_miss=%s\n" "$k" "$a" "$n" "$u" \
    "$(med "$k q-n$n-k$a" ns_per_active_step)" "$(med "$k q-n$n-k$a" words)" "$ins" "$cyc" "$l1" "$llc"
done; done; done | tee "$RES/summary.txt"
for k in $KITS; do for p in sort wfi; do echo "== chip $p in windows of 64"; cat "$RES/windows-$k-$p.txt"; done; done | tee -a "$RES/summary.txt"
[ "$FAILS" = 0 ] && verdict "every run completed" PASS || verdict "every run completed ($FAILS failed)" FAIL
sec "done in $(($(date +%s) - START)) s"
} 2>&1 | tee "$RES/run.log"
grep '^VERDICT' "$RES/run.log" > "$RES/VERDICTS.txt"
rm -rf "$W"
grep -q ': FAIL$' "$RES/VERDICTS.txt" && exit 1
exit 0
